# Definindo as classes base e derivadas
class Livro:
    def __init__(self, titulo, preco):
        self.titulo = titulo
        self.preco = preco

    def calcular_custo(self):
        return self.preco


class LivroFisico(Livro):
    def __init__(self, titulo, preco, tamanho):
        super().__init__(titulo, preco)
        self.tamanho = tamanho

    def calcular_custo(self):
        return super().calcular_custo() + 10 * self.tamanho


class LivroDigital(Livro):
    def __init__(self, titulo, preco, formato):
        super().__init__(titulo, preco)
        self.formato = formato

    def calcular_custo(self):
        return super().calcular_custo() + 5 * self.formato


class LivroAudio(Livro):
    def __init__(self, titulo, preco, duracao):
        super().__init__(titulo, preco)
        self.duracao = duracao

    def calcular_custo(self):
        return super().calcular_custo() + 2 * self.duracao


# Definindo a classe Pedido
class Pedido:
    def __init__(self):
        self.itens = []

    def adicionar_item(self, item):
        self.itens.append(item)

    def calcular_total(self):
        total = 0
        for item in self.itens:
            total += item.calcular_custo()
        return total


# Definindo a classe Gerenciador de Bibliotecas
class GerenciadorBibliotecas:
    def __init__(self):
        self.biblioteca = []

    def adicionar_livro(self, livro):
        self.biblioteca.append(livro)

    def filtrar_por_tipo(self, tipo):
        return [livro for livro in self.biblioteca if isinstance(livro, tipo)]


